typedef struct {
    volatile uint32_t RBR_THR; /* 0x0000: Receiver Buffer Register (read, DLAB=0) / Transmit Holding Register (write, DLAB=0) / Baud Divisor Low byte (DLAB=1). Read: received byte.  Write: byte to transmit. DLAB=1 access handled in HAL code via raw pointer.
 */
    volatile uint32_t IER; /* 0x0004: Interrupt Enable Register (DLAB=0) / Baud Divisor High byte (DLAB=1). DLAB=1 access handled in HAL code via raw pointer.
 */
    volatile uint32_t FCR_IIR; /* 0x0008: FIFO Control Register (write) / Interrupt Identification Register (read). Reads return IIR; writes configure FIFO via FCR fields. FCR is write-only; IIR is read-only.
 */
    volatile uint32_t LCR; /* 0x000c: Line Control Register. Controls data format and DLAB. */
    volatile uint32_t MCR; /* 0x0010: Modem Control Register. */
    volatile uint32_t LSR; /* 0x0014: Line Status Register. TX/RX status flags. */
    volatile uint32_t MSR; /* 0x0018: Modem Status Register. */
    volatile uint32_t SCR; /* 0x001c: Scratch Register. Read/write with no hardware effect. */
} UART_V1_UARTTypeDef;

