typedef struct {
    volatile uint32_t STATUS; /* 0x0000: Counter Status Register (WDT00). Read-only. Current down-counter value in microseconds. Loaded from RELOAD on reset or restart (0x4755 write to RESTART). Counts down to 0 when WDT is enabled. Default / power-on value: 0x014F_B180 (~22 s).
 */
    volatile uint32_t RELOAD; /* 0x0004: Counter Reload Value Register (WDT04). Value loaded into STATUS on reset or when 0x4755 is written to the RESTART register.  Units: microseconds. Default: 0x014F_B180 (~22 s).
 */
    volatile uint32_t RESTART; /* 0x0008: Counter Restart Register (WDT08). Write-only trigger. Write 0x4755 to reload STATUS from RELOAD and restart the counter (provided CTRL.WDT_EN=1).  Any other write value is ignored.
 */
    volatile uint32_t CTRL; /* 0x000c: Control Register (WDT0C). Configures reset mode, interrupt, and enable. Default: 0x0010 (WDT_EN=0, RST_SYS=1 = SOC reset mode).
 */
    volatile uint8_t _pad0x24[20];
    volatile uint32_t SW_RESET_CTRL; /* 0x0024: Software Mode Reset Control Register (WDT24). Write 0xAEED_F123 to trigger an immediate software-mode SOC reset (after setting SW_RESET_MASK1 to select which blocks to reset). This bit clears automatically after reset.
 */
    volatile uint32_t SW_RESET_MASK1; /* 0x0028: Software Mode Reset Mask Register #1 (WDT28). Each bit enables the corresponding subsystem to be reset when SW_RESET_CTRL is triggered. Zephyr uses 0x3FFF_FF1 to reset most subsystems.
 */
} WDT_V1_WDTTypeDef;

